def set_geometry_source(
    *,
    element: ElementId,
    source: Literal["direct", "parametric"],
    in_design_option: Optional[Any] = None,
) -> Dict[str, Any]:
    """Switch where an element's geometry comes from. 'direct': freeze a parametric wall
    / floor so it can be edited freely like a SketchUp group (keeps category, type,
    parameters; hosted doors / windows freeze with it). 'parametric': turn a directly
    edited wall (rectangular box) or floor (flat slab with vertical sides) back into a
    parametric one, using a type of the same thickness; fails with
    ferro.model.not_recognised or ferro.model.no_matching_type. Returns {element,
    changed}.

    Args:
        element: Element id.
        source: One of: direct, parametric.
        in_design_option: Where the change lands: a design option id (the change goes
            into that option's layer), or "shared" for the shared model. Omitted (or
            null): the option the user is editing in the Ferro app, else the shared
            model. Optional.

    Returns:
        The tool's JSON body. Raises FerroError on failure.
    """
    args: Dict[str, Any] = {"element": element, "source": source}
    if in_design_option is not None:
        args["in_design_option"] = in_design_option
    return _call("set_geometry_source", args)


